<script setup>
import { onMounted } from 'vue'; import { useAdminStore } from '../stores/useAdminStore.js'; import AdminStatePanel from '../components/AdminStatePanel.vue'; import AdminTable from '../components/AdminTable.vue';
const admin=useAdminStore(); const connections=admin.resources.connections; const incidents=admin.resources.incidents; const connectionColumns=[{key:'storeId',label:'매장'},{key:'provider',label:'Provider'},{key:'externalStoreId',label:'외부 매장'},{key:'enabled',label:'활성화'},{key:'connectionStatus',label:'연결 상태'},{key:'lastErrorCode',label:'최근 처리 오류'},{key:'unresolvedBlockedCount',label:'BLOCKED'}]; const incidentColumns=[{key:'inboxId',label:'Inbox'},{key:'storeId',label:'매장'},{key:'provider',label:'Provider'},{key:'externalOrderId',label:'외부 주문'},{key:'processingStatus',label:'처리 상태'},{key:'lastErrorCode',label:'오류 코드'},{key:'lastErrorAt',label:'발생일'}]; const formatDate=v=>v?new Date(v).toLocaleString('ko-KR'):'-'; const load=()=>Promise.allSettled([admin.loadConnections(),admin.loadIncidents()]); onMounted(load);
</script>
<template><div class="sections"><section><h2>플랫폼 연결</h2><p>연결 상태와 처리 오류는 서로 다른 값으로 표시됩니다.</p><AdminStatePanel :loading="connections.loading" :error="connections.error" :empty="connections.data?.items?.length===0" empty-text="플랫폼 연결이 없습니다." @retry="admin.loadConnections().catch(()=>{})"><AdminTable :columns="connectionColumns" :rows="connections.data?.items||[]"><template #enabled="{row}">{{row.enabled?'사용':'중지'}}</template></AdminTable></AdminStatePanel></section><section><h2>BLOCKED·재시도 처리 오류</h2><p>이번 P0에서는 조회만 제공하며 강제 재처리나 상태 수정은 제공하지 않습니다.</p><AdminStatePanel :loading="incidents.loading" :error="incidents.error" :empty="incidents.data?.items?.length===0" empty-text="현재 처리 오류가 없습니다." @retry="admin.loadIncidents().catch(()=>{})"><AdminTable :columns="incidentColumns" :rows="incidents.data?.items||[]"><template #lastErrorAt="{row}">{{formatDate(row.lastErrorAt)}}</template></AdminTable></AdminStatePanel></section></div></template>
<style scoped>.sections{display:grid;gap:26px}h2{margin:0 0 6px;font-size:20px}p{margin:0 0 14px;color:#64748b}</style>
